mapper.select:
SELECT b.board_id, b.member_id, b.category, b.title, b.content, b.count, b.like_count, (SELECT COUNT(*) FROM board_comment bc WHERE bc.board_id = b.board_id) AS comment_count, b.create_at, DATE_FORMAT(b.create_at, '%Y-%m-%d %H:%i') AS create_at_str, b.update_at, m.nickname, COALESCE(NULLIF(m.profile, ''), '/images/common_member.png') AS profile FROM board b
LEFT JOIN member m ON b.member_id = m.member_id
ORDER BY b.create_at DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE board
SET category = #{category},
    title = #{title},
    content = #{content}
WHERE board_id = #{boardId}
  AND member_id = #{memberId}

